53	function shellQuote(value: string): string {
54	  return `'${value.replace(/'/g, "'\\''")}'`;
55	}
56	
57	function safeTaskName(value: string): string {
58	  return value.replace(/[^A-Za-z0-9_.-]/g, '-').slice(0, 120);
59	}
