61	function withSpriteTaskHeartbeat(command: string, taskName: string): string {
62	  const quotedTaskName = shellQuote(taskName);
63	  return [
64	    `TASK_NAME=${quotedTaskName}`,
65	    `TASK_EXPIRE=5m`,
66	    `sprite_task_api() { curl -sS --unix-socket /.sprite/api.sock -H "Content-Type: application/json" "$@" >/dev/null 2>&1 || true; }`,
67	    `sprite_task_put() { sprite_task_api -X PUT "http://sprite/v1/tasks/$TASK_NAME" -d "{\\"expire\\":\\"$TASK_EXPIRE\\"}"; }`,
68	    `sprite_task_delete() { sprite_task_api -X DELETE "http://sprite/v1/tasks/$TASK_NAME"; }`,
69	    'cleanup() { status=$?; trap - EXIT INT TERM; if [ -n "${LOG_HBEAT:-}" ]; then kill "$LOG_HBEAT" 2>/dev/null || true; wait "$LOG_HBEAT" 2>/dev/null || true; fi; if [ -n "${TASK_HBEAT:-}" ]; then kill "$TASK_HBEAT" 2>/dev/null || true; wait "$TASK_HBEAT" 2>/dev/null || true; fi; sprite_task_delete; exit "$status"; }',
70	    `trap cleanup EXIT INT TERM`,
71	    `sprite_task_put`,
72	    `(while true; do sleep 60; sprite_task_put; done) & TASK_HBEAT=$!`,
73	    `(while true; do sleep 20; printf . >&2; done) & LOG_HBEAT=$!`,
74	    command,
75	  ].join('; ');
76	}
