78	function classifyCodexAuthIssue(raw: string): string | undefined {
79	  const text = raw.toLowerCase();
80	  const matchesAuthIssue =
81	    text.includes('codex login') ||
82	    text.includes('not logged') ||
83	    text.includes('authentication') ||
84	    text.includes('unauthorized') ||
85	    text.includes('forbidden') ||
86	    text.includes('openai_api_key') ||
87	    text.includes('api key') ||
88	    text.includes('login required') ||
89	    text.includes('chatgpt login') ||
90	    text.includes('status code: 401') ||
91	    text.includes('status code: 403');
92	
93	  if (!matchesAuthIssue) return undefined;
94	
95	  return [
96	    'Codex is not authenticated in this sprite environment.',
97	    'Run `codex login status` and then `codex login` inside the sprite shell, or switch this chat to Claude.',
98	  ].join(' ');
99	}
100	
101	function messagePlainText(message: ChatMessage): string {
102	  return message.content
103	    .filter((item): item is Extract<ChatContent, { type: 'text' }> => item.type === 'text')
104	    .map((item) => item.text)
105	    .join('\n\n')
106	    .trim();
107	}
108	
109	function buildFallbackPrompt(history: ChatMessage[], prompt: string): string {
110	  const transcript = history
111	    .filter((message) => message.role === 'user' || message.role === 'assistant')
112	    .map((message) => {
113	      const text = messagePlainText(message);
114	      if (!text) return null;
115	      const role = message.role === 'user' ? 'User' : 'Assistant';
116	      const clipped = text.length > 1200 ? `${text.slice(0, 1200)}...` : text;
117	      return `${role}: ${clipped}`;
118	    })
119	    .filter((line): line is string => line !== null)
120	    .slice(-12);
121	
122	  if (transcript.length === 0) return prompt;
123	
124	  return [
125	    'Continue this conversation. Here is the prior transcript:',
126	    transcript.join('\n\n'),
127	    `User: ${prompt}`,
128	    'Assistant:',
129	  ].join('\n\n');
130	}
131	
132	function countUserMessages(messages: ChatMessage[]): number {
133	  return messages.reduce((n, m) => (m.role === 'user' ? n + 1 : n), 0);
134	}
135	
136	/** Stable content fingerprint — two conversations with the same signature render identically. */
137	function conversationSignature(messages: ChatMessage[]): string {
138	  return messages
139	    .map((m) => {
140	      const parts = m.content.map((c) => {
141	        if (c.type === 'text') return `t:${c.text}`;
142	        if (c.type === 'reasoning') return `r:${c.text.length}`;
143	        if (c.type === 'toolUse') return `u:${c.card.toolUseId}`;
144	        if (c.type === 'toolResult') return `R:${c.card.toolUseId}`;
145	        return c.type;
146	      });
147	      return `${m.role}|${parts.join('|')}`;
148	    })
149	    .join('\n');
150	}
151	
152	/**
153	 * Overlay an incoming (e.g. on-disk transcript) conversation onto the local one,
154	 * preserving the existing message ids for the common prefix. Keeping ids stable
155	 * means React reuses the already-mounted bubbles instead of remounting/re-scrolling
156	 * them — which is what made reopening a chat look like the last turn was duplicated
157	 * and re-answered.
158	 */
159	function mergeTranscript(local: ChatMessage[], incoming: ChatMessage[]): ChatMessage[] {
160	  return incoming.map((msg, i) => {
161	    const localMsg = local[i];
162	    if (localMsg && localMsg.role === msg.role) {
163	      return { ...msg, id: localMsg.id };
164	    }
165	    return msg;
166	  });
167	}
168	
169	function nextAssistantAfterUser(messages: ChatMessage[], userIndex: number): number {
170	  for (let i = userIndex + 1; i < messages.length; i++) {
171	    if (messages[i].role === 'user') break;
172	    if (messages[i].role === 'assistant') return i;
173	  }
174	  return -1;
175	}
