187	function redactDebugText(value: string): string {
188	  return value
189	    .replace(/Bearer\s+[A-Za-z0-9._~+/=-]+/gi, 'Bearer [redacted]')
190	    .replace(/sk-[A-Za-z0-9_-]{10,}/g, 'sk-[redacted]')
191	    .replace(/(OPENAI_API_KEY|CLAUDE_CODE_OAUTH_TOKEN)=\S+/g, '$1=[redacted]');
192	}
193	
194	function compactDebugChunk(value: string, max = DEBUG_SNIPPET_MAX): string {
195	  const cleaned = redactDebugText(stripLogTimestamps(value))
196	    .replace(/\u001b\[[0-9;]*m/g, '')
197	    .replace(/\r/g, '\\r')
198	    .replace(/\n/g, '\\n')
199	    .trim();
200	  if (cleaned.length <= max) return cleaned;
201	  return `${cleaned.slice(0, max)}…`;
202	}
203	
204	function isHeartbeatStderr(value: string): boolean {
205	  const compact = stripLogTimestamps(value).replace(/\s/g, '');
206	  return compact.length > 0 && /^\.+$/.test(compact);
207	}
