209	function codexEventDebugLabel(event: CodexStreamEvent): string {
210	  switch (event.type) {
211	    case 'unknown':
212	      return [
213	        'unknown',
214	        event.rawType ? `raw=${event.rawType}` : undefined,
215	        event.itemType ? `item=${event.itemType}` : undefined,
216	        event.keys?.length ? `keys=${event.keys.join('|')}` : undefined,
217	      ].filter(Boolean).join(' ');
218	    case 'assistantDelta':
219	      return `assistantDelta chars=${event.text.length}`;
220	    case 'reasoning':
221	      return `reasoning chars=${event.text.length}`;
222	    case 'commandBegin':
223	      return `commandBegin id=${event.commandId}`;
224	    case 'commandEnd':
225	      return `commandEnd id=${event.commandId} exit=${event.exitCode ?? '?'}`;
226	    case 'fileChange':
227	      return `fileChange files=${event.files.length}`;
228	    case 'mcpToolBegin':
229	      return `mcpToolBegin tool=${event.server ? `${event.server}.` : ''}${event.tool}`;
230	    case 'mcpToolEnd':
231	      return `mcpToolEnd tool=${event.server ? `${event.server}.` : ''}${event.tool} error=${event.isError}`;
232	    case 'todoList':
233	      return `todoList items=${event.items.length}`;
234	    default:
235	      return event.type;
236	  }
237	}
238	
239	type ChatTurnTiming = {
240	  startedAt?: number;
241	  firstStdoutAt?: number;
242	  firstStderrAt?: number;
243	  firstParsedAt?: number;
244	  firstAssistantAt?: number;
245	};
246	
247	export function useChat(options: UseChatOptions) {
248	  const { spriteName, chatId, workingDirectory, provider } = options;
249	
250	  const [messages, setMessages] = useState<ChatMessage[]>([]);
251	  const [status, setStatus] = useState<ChatStatus>('idle');
252	  const [modelName, setModelName] = useState<string | undefined>();
253	  const [errorMessage, setErrorMessage] = useState<string | undefined>();
254	  const [inputText, setInputText] = useState('');
255	  const [codexAuthIssue, setCodexAuthIssue] = useState<string | undefined>();
256	
257	  const claudeSessionIdRef = useRef<string | undefined>(options.initialClaudeSessionId);
258	  const codexSessionIdRef = useRef<string | undefined>(options.initialCodexSessionId);
259	  const activeRunRef = useRef<ActiveChatRun | undefined>(options.initialActiveRun);
260	  const execSessionIdRef = useRef<string | undefined>(undefined);
261	  const abortRef = useRef<AbortController | null>(null);
262	  const claudeParserRef = useRef(new ClaudeStreamParser());
263	  const codexParserRef = useRef(new CodexStreamParser());
264	  const loadRequestRef = useRef(0);
265	  const loadedChatIdRef = useRef<string | undefined>(undefined);
266	  const messagesRef = useRef<ChatMessage[]>([]);
267	  const activeUserMessageIdRef = useRef<string | undefined>(undefined);
268	  const activeAssistantMessageIdRef = useRef<string | undefined>(undefined);
269	  const toolUseIndexRef = useRef<Map<string, { messageIndex: number; toolName: string }>>(new Map());
270	  const processedUUIDsRef = useRef<Set<string>>(new Set());
271	  const statusRef = useRef<ChatStatus>('idle');
272	  const assistantTextSeenRef = useRef(false);
273	  const serviceEventsSeenRef = useRef(0);
274	  const codexStderrRef = useRef('');
275	  const codexSawAssistantRef = useRef(false);
276	  const agentTurnCompleteRef = useRef(false);
277	  const turnTimingRef = useRef<ChatTurnTiming>({});
278	  const detachingControllersRef = useRef<Set<AbortController>>(new Set());
279	  const processServiceEventRef = useRef<(event: ServiceLogEvent) => void>(() => {});
280	
281	  const setStatusTracked = useCallback((s: ChatStatus) => {
282	    statusRef.current = s;
283	    setStatus(s);
284	  }, []);
285	
286	  const emitSessionIds = useCallback(() => {
287	    options.onSessionIdsChange?.({
288	      claudeSessionId: claudeSessionIdRef.current,
289	      codexSessionId: codexSessionIdRef.current,
290	    });
291	  }, [options.onSessionIdsChange]);
292	
293	  const setActiveRun = useCallback(
294	    (activeRun: ActiveChatRun | undefined) => {
295	      activeRunRef.current = activeRun;
296	      options.onActiveRunChange?.(activeRun);
297	    },
298	    [options.onActiveRunChange]
299	  );
300	
301	  const setClaudeSessionId = useCallback(
302	    (sessionId: string | undefined) => {
303	      if (claudeSessionIdRef.current === sessionId) return;
304	      claudeSessionIdRef.current = sessionId;
305	      emitSessionIds();
306	    },
307	    [emitSessionIds]
308	  );
309	
310	  const setCodexSessionId = useCallback(
311	    (sessionId: string | undefined) => {
312	      if (codexSessionIdRef.current === sessionId) return;
313	      codexSessionIdRef.current = sessionId;
314	      emitSessionIds();
315	    },
316	    [emitSessionIds]
317	  );
318	
319	  const isStreaming =
320	    status === 'streaming' ||
321	    status === 'connecting' ||
322	    status === 'reconnecting' ||
323	    activeRunRef.current !== undefined;
324	
325	  const updateMessages = useCallback((updater: (prev: ChatMessage[]) => ChatMessage[]) => {
326	    setMessages((prev) => {
327	      const next = updater(prev);
328	      messagesRef.current = next;
329	      return next;
330	    });
331	  }, []);
332	
333	  const persistMessages = useCallback(
334	    async (msgs?: ChatMessage[]) => {
335	      await chatRepository.setMessages(chatId, msgs ?? messagesRef.current);
336	    },
337	    [chatId]
338	  );
339	
340	  const syncClaudeTranscript = useCallback(
341	    async (loadRequest: number, resumeId: string | undefined) => {
342	      if (provider !== 'claude' || !resumeId) return;
343	
344	      try {
345	        const transcript = await readClaudeSessionMessages(spriteName, resumeId);
346	        if (loadRequest !== loadRequestRef.current) return;
347	        if (statusRef.current !== 'idle') return;
348	        if (transcript.length === 0) return;
349	        const local = messagesRef.current;
350	        const transcriptTurns = countUserMessages(transcript);
351	        const localTurns = countUserMessages(local);
352	        // The app may already have persisted the user's in-flight turn before
353	        // it was closed. In that case the turn counts are equal, but the
354	        // transcript can now contain the completed assistant response.
355	        if (local.length !== 0 && transcriptTurns < localTurns) return;
356	        const merged = mergeTranscript(local, transcript);
357	        if (conversationSignature(merged) === conversationSignature(local)) return;
358	        messagesRef.current = merged;
359	        setMessages(merged);
360	        await chatRepository.setMessages(chatId, merged);
361	      } catch {
362	        // Offline / no transcript yet — keep the local copy.
363	      }
364	    },
365	    [chatId, provider, spriteName]
366	  );
367	
368	  // Codex counterpart of syncClaudeTranscript: pull the on-disk rollout for a
369	  // resumed Codex thread so turns that finished while the app was away (or ran
370	  // from a terminal) are recovered — the same history `codex exec resume` sees.
371	  const syncCodexTranscript = useCallback(
372	    async (loadRequest: number, resumeId: string | undefined) => {
373	      if (!isCodexProvider(provider) || !resumeId) return;
374	
375	      try {
376	        const transcript = await readCodexSessionMessages(spriteName, resumeId);
377	        if (loadRequest !== loadRequestRef.current) return;
378	        if (statusRef.current !== 'idle') return;
379	        if (transcript.length === 0) return;
380	        const local = messagesRef.current;
381	        const transcriptTurns = countUserMessages(transcript);
382	        const localTurns = countUserMessages(local);
383	        if (local.length !== 0 && transcriptTurns < localTurns) return;
384	        const merged = mergeTranscript(local, transcript);
385	        if (conversationSignature(merged) === conversationSignature(local)) return;
386	        messagesRef.current = merged;
387	        setMessages(merged);
388	        await chatRepository.setMessages(chatId, merged);
389	      } catch {
390	        // Offline / no rollout yet — keep the local copy.
391	      }
392	    },
393	    [chatId, provider, spriteName]
394	  );
395	
396	  const loadSession = useCallback(async () => {
397	    const loadRequest = ++loadRequestRef.current;
398	    const isDifferentChat = loadedChatIdRef.current !== chatId;
399	    if (isDifferentChat && statusRef.current === 'idle') {
400	      messagesRef.current = [];
401	      setMessages([]);
402	      toolUseIndexRef.current = new Map();
403	      activeUserMessageIdRef.current = undefined;
404	      activeAssistantMessageIdRef.current = undefined;
405	      assistantTextSeenRef.current = false;
406	      serviceEventsSeenRef.current = 0;
407	      claudeParserRef.current.reset();
408	      codexParserRef.current.reset();
409	      codexStderrRef.current = '';
410	      codexSawAssistantRef.current = false;
411	      turnTimingRef.current = {};
412	      setErrorMessage(undefined);
413	      setCodexAuthIssue(undefined);
414	      claudeSessionIdRef.current = options.initialClaudeSessionId;
415	      codexSessionIdRef.current = options.initialCodexSessionId;
416	      activeRunRef.current = options.initialActiveRun;
417	      execSessionIdRef.current = undefined;
418	    }
419	    const initialMessageCount = messagesRef.current.length;
420	    const saved = await chatRepository.getMessages(chatId);
421	    if (loadRequest !== loadRequestRef.current) return;
422	
423	    // Avoid clobbering live in-memory messages if a send started while loading persisted history.
424	    if (messagesRef.current.length > initialMessageCount || statusRef.current !== 'idle') return;
425	
426	    messagesRef.current = saved;
427	    loadedChatIdRef.current = chatId;
428	    setMessages(saved);
429	    activeRunRef.current = options.initialActiveRun;
430	    activeUserMessageIdRef.current = undefined;
431	    activeAssistantMessageIdRef.current = undefined;
432	    assistantTextSeenRef.current = false;
433	    agentTurnCompleteRef.current = false;
434	
435	    setClaudeSessionId(options.initialClaudeSessionId);
436	    setCodexSessionId(options.initialCodexSessionId);
437	
438	    const index = new Map<string, { messageIndex: number; toolName: string }>();
439	    saved.forEach((msg, idx) => {
440	      msg.content.forEach((item) => {
441	        if (item.type === 'toolUse') {
442	          index.set(item.card.toolUseId, { messageIndex: idx, toolName: item.card.toolName });
443	        }
444	      });
445	    });
446	    toolUseIndexRef.current = index;
447	
448	    if (saved.length === 0) {
449	      processedUUIDsRef.current = new Set();
450	      claudeParserRef.current.reset();
451	      codexParserRef.current.reset();
452	    }
453	
454	    const activeRun = options.initialActiveRun;
455	    if (activeRun && activeRun.provider === provider) {
456	      activeUserMessageIdRef.current = activeRun.userMessageId;
457	      activeAssistantMessageIdRef.current = activeRun.assistantMessageId;
458	      execSessionIdRef.current = activeRun.execSessionId;
459	      processedUUIDsRef.current = new Set();
460	      claudeParserRef.current.reset();
461	      codexParserRef.current.reset();
462	      codexStderrRef.current = '';
463	      codexSawAssistantRef.current = false;
464	      agentTurnCompleteRef.current = false;
465	      serviceEventsSeenRef.current = 0;
466	      turnTimingRef.current = { startedAt: Date.now() };
467	      setStatusTracked('reconnecting');
468	
469	      (async () => {
470	        const controller = new AbortController();
471	        let disconnectedBeforeExit = false;
472	        abortRef.current = controller;
473	        try {
474	          await api.streamExec(
475	            spriteName,
476	            [],
477	            (event) => {
478	              if (abortRef.current !== controller) return;
479	              processServiceEvent(event);
480	            },
481	            controller.signal,
482	            {
483	              attachSessionId: activeRun.execSessionId,
484	              onDisconnectBeforeExit: () => {
485	                disconnectedBeforeExit = true;
486	              },
487	            }
488	          );
489	        } catch (err: any) {
490	          if (err.name !== 'AbortError') {
491	            debugChat('active exec attach failed', provider, err.message ?? err);
492	          }
493	        } finally {
494	          const wasDetaching = detachingControllersRef.current.delete(controller);
495	          const isCurrentStream = abortRef.current === controller;
496	          if (isCurrentStream) {
497	            abortRef.current = null;
498	          }
499	          if (wasDetaching && !agentTurnCompleteRef.current) {
500	            debugChat('active exec detached', provider, activeRun.execSessionId);
501	            if (isCurrentStream) setStatusTracked('idle');
502	            await persistMessages();
503	            return;
504	          }
505	          if (disconnectedBeforeExit && activeRunRef.current?.execSessionId === activeRun.execSessionId && !agentTurnCompleteRef.current) {
506	            if (isCurrentStream) setStatusTracked('idle');
507	            await persistMessages();
508	            return;
509	          }
510	          execSessionIdRef.current = undefined;
511	          activeUserMessageIdRef.current = undefined;
512	          activeAssistantMessageIdRef.current = undefined;
513	          assistantTextSeenRef.current = false;
514	          if (activeRunRef.current?.execSessionId === activeRun.execSessionId) {
515	            setActiveRun(undefined);
516	          }
517	          if (isCurrentStream) setStatusTracked('idle');
518	          await syncClaudeTranscript(loadRequest, options.initialClaudeSessionId);
519	          await syncCodexTranscript(loadRequest, options.initialCodexSessionId);
520	          await persistMessages();
521	        }
522	      })();
523	      return;
524	    }
525	
526	    if (activeRun) {
527	      setActiveRun(undefined);
528	    }
529	
530	    // Source-of-truth sync: if this chat resumes a known Claude session, pull its
531	    // on-disk transcript from the sprite. Catches turns that finished (or were
532	    // started from a terminal / another device) while the app was away — the same
533	    // history `claude --resume` would show. Runs in the background; guarded so it
534	    // never clobbers a fresh local send.
535	    syncClaudeTranscript(loadRequest, options.initialClaudeSessionId);
536	    syncCodexTranscript(loadRequest, options.initialCodexSessionId);
537	  }, [
538	    chatId,
539	    options.initialActiveRun,
540	    options.initialClaudeSessionId,
541	    options.initialCodexSessionId,
542	    persistMessages,
543	    provider,
544	    setClaudeSessionId,
545	    setCodexSessionId,
546	    setActiveRun,
547	    setStatusTracked,
548	    spriteName,
549	    syncClaudeTranscript,
550	    syncCodexTranscript,
551	  ]);
552	
553	  const ensureAssistantTarget = useCallback(
554	    (source: ChatMessage[]): { messages: ChatMessage[]; index: number } => {
555	      let messages = source;
556	      const activeId = activeAssistantMessageIdRef.current;
557	      const activeUserId = activeUserMessageIdRef.current;
558	
559	      if (activeId) {
560	        const byId = messages.findIndex((m) => m.id === activeId && m.role === 'assistant');
561	        if (byId !== -1) return { messages, index: byId };
562	      }
563	
564	      if (activeUserId) {
565	        const userIndex = messages.findIndex((m) => m.id === activeUserId && m.role === 'user');
566	        if (userIndex !== -1) {
