1180	      await ensureProvisionedOnce(spriteName);
1181	
1182	      commandParts.push(`mkdir -p ${shellQuote(workingDirectory)}`);
1183	      commandParts.push(`cd ${shellQuote(workingDirectory)}`);
1184	      // Load the persisted Claude OAuth token (env-var path); harmless no-op when
1185	      // a captured login credentials file is used instead.
1186	      commandParts.push('. ~/.sprite_env 2>/dev/null || true');
1187	
1188	      if (provider === 'claude') {
1189	        const claudePrompt = claudeSessionIdRef.current
1190	          ? prompt
1191	          : buildFallbackPrompt(historyBeforeSend, prompt);
1192	
1193	        commandParts.push('export NO_DNA=1');
1194	
1195	        let claudeCmd =
1196	          'claude -p --verbose --output-format stream-json --dangerously-skip-permissions';
1197	
1198	        const [modelId, maxTurns, customInstructions] = await Promise.all([
1199	          getSetting('claudeModel'),
1200	          getSetting('maxTurns'),
1201	          getSetting('customInstructions'),
1202	        ]);
1203	
1204	        claudeCmd += ` --model ${shellQuote(modelId ?? 'sonnet')}`;
1205	
1206	        if (maxTurns && maxTurns !== '0') {
1207	          claudeCmd += ` --max-turns ${shellQuote(maxTurns)}`;
1208	        }
1209	
1210	        if (customInstructions && customInstructions.trim()) {
1211	          claudeCmd += ` --append-system-prompt ${shellQuote(customInstructions)}`;
1212	        }
1213	
1214	        if (claudeSessionIdRef.current) {
1215	          claudeCmd += ` --resume ${shellQuote(claudeSessionIdRef.current)}`;
1216	        }
1217	        claudeCmd += ` ${shellQuote(claudePrompt)}`;
1218	
1219	        commandParts.push(claudeCmd);
1220	      } else {
1221	        const codexModelSetting = await getSetting('codexModel');
1222	        const codexModel = codexModelSetting?.trim();
1223	        setModelName(codexModel || CODEX_DEFAULT_MODEL_LABEL);
1224	        const codexPrompt = codexSessionIdRef.current
1225	          ? prompt
1226	          : buildFallbackPrompt(historyBeforeSend, prompt);
