1239	          }
1240	          if (codexSessionIdRef.current) {
1241	            codexCmd += ` ${shellQuote(codexSessionIdRef.current)}`;
1242	          }
1243	          codexCmd += ` ${shellQuote(codexPrompt)}`;
1244	          commandParts.push(codexCmd);
1245	        }
1246	      }
1247	
1248	      const taskName = safeTaskName(`wisp-chat-${provider}-${userMessage.id}`);
1249	      const fullCommand = withSpriteTaskHeartbeat(commandParts.join(' && '), taskName);
1250	
1251	      processedUUIDsRef.current = new Set();
1252	      claudeParserRef.current.reset();
1253	      codexParserRef.current.reset();
1254	      codexStderrRef.current = '';
1255	      codexSawAssistantRef.current = false;
1256	      agentTurnCompleteRef.current = false;
1257	      turnTimingRef.current = { startedAt: turnTimingRef.current.startedAt ?? Date.now() };
1258	      setStatusTracked('connecting');
1259	      setErrorMessage(undefined);
1260	      setCodexAuthIssue(undefined);
1261	      serviceEventsSeenRef.current = 0;
1262	
1263	      const abortController = new AbortController();
1264	      abortRef.current = abortController;
1265	      execSessionIdRef.current = undefined;
1266	      let disconnectedBeforeExit = false;
1267	      const streamActiveRunRef: { current?: ActiveChatRun } = {};
1268	
1269	      try {
1270	        const onSessionId = (sessionId: string) => {
1271	          execSessionIdRef.current = sessionId;
1272	          const nextRun: ActiveChatRun = {
1273	            execSessionId: sessionId,
1274	            taskName,
1275	            provider,
1276	            transport,
1277	            userMessageId: userMessage.id,
1278	            assistantMessageId: assistantMessage.id,
1279	            workingDirectory,
1280	            startedAt: Date.now(),
1281	          };
1282	          streamActiveRunRef.current = nextRun;
1283	          setActiveRun(nextRun);
1284	        };
1285	
1286	        const onDisconnectBeforeExit = () => {
1287	          disconnectedBeforeExit = true;
1288	        };
1289	
1290	        const onEvent = (event: ServiceLogEvent) => {
1291	          if (abortRef.current !== abortController) return;
1292	          processServiceEvent(event);
1293	        };
1294	
1295	        if (provider === 'codexAppServer' && codexAppServerPrompt !== undefined) {
1296	          await streamCodexAppServerTurn({
1297	            spriteName,
1298	            command: ['bash', '-c', fullCommand],
1299	            path: '/bin/bash',
1300	            workingDirectory,
1301	            prompt: codexAppServerPrompt,
1302	            threadId: codexSessionIdRef.current,
1303	            model: codexAppServerModel,
1304	            maxRunAfterDisconnect: CHAT_MAX_RUN_AFTER_DISCONNECT,
1305	            signal: abortController.signal,
1306	            onEvent,
1307	            onDisconnectBeforeExit,
1308	            onSessionId,
