1327	          debugChat('stream error', provider, message);
1328	          setErrorMessage(message);
1329	          if (isCodexProvider(provider)) {
1330	            reportCodexAuthIssue(`${message}\n${codexStderrRef.current}`);
1331	          }
1332	        }
1333	      } finally {
1334	        const wasDetaching = detachingControllersRef.current.delete(abortController);
1335	        const isCurrentStream = abortRef.current === abortController;
1336	        if (isCurrentStream) {
