1342	            debugChat('stream detached', provider, streamActiveRun.execSessionId);
1343	          } else {
1344	            debugChat('stream detached before session id', provider);
1345	          }
1346	          if (isCurrentStream) setStatusTracked('idle');
1347	          await persistMessages();
1348	          return;
1349	        }
1350	
1351	        const remaining =
1352	          provider === 'claude' ? claudeParserRef.current.flush() : codexParserRef.current.flush();
1353	
1354	        if (provider === 'claude') {
1355	          for (const parsed of remaining as ClaudeStreamEvent[]) {
1356	            if (parsed.uuid && processedUUIDsRef.current.has(parsed.uuid)) continue;
1357	            if (parsed.uuid) processedUUIDsRef.current.add(parsed.uuid);
1358	            handleClaudeEvent(parsed);
1359	          }
