1376	        const currentActiveRun = activeRunRef.current as ActiveChatRun | undefined;
1377	        if (!streamExecSessionId || currentActiveRun?.execSessionId === streamExecSessionId) {
1378	          setActiveRun(undefined);
1379	        }
1380	        execSessionIdRef.current = undefined;
1381	        activeUserMessageIdRef.current = undefined;
1382	        activeAssistantMessageIdRef.current = undefined;
1383	        assistantTextSeenRef.current = false;
1384	        if (isCurrentStream) setStatusTracked('idle');
1385	        await persistMessages();
1386	      }
1387	    },
1388	    [
1389	      inputText,
1390	      chatId,
1391	      loadSession,
1392	      persistMessages,
1393	      processServiceEvent,
1394	      provider,
1395	      reportCodexAuthIssue,
1396	      setActiveRun,
1397	      setStatusTracked,
1398	      spriteName,
