285	function readEntryFlag(raw: Record<string, unknown>, keys: string[]): boolean | undefined {
286	  for (const key of keys) {
287	    const value = raw[key];
288	    if (typeof value === 'boolean') return value;
289	  }
290	  return undefined;
291	}
