293	/**
294	 * The `fs/list` entry shape isn't strictly specified, so normalize defensively:
295	 * accept camelCase / snake_case / `type` / a leading `mode` char (`drwx…`, `lrwx…`).
296	 */
297	function normalizeFileEntry(raw: unknown, dirPath: string): SpriteFileEntry {
298	  const obj = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
299	  const name = String(obj.name ?? obj.Name ?? '');
300	  const rawPath = obj.path ?? obj.Path;
301	  const path = typeof rawPath === 'string' && rawPath ? rawPath : joinFsPath(dirPath, name);
302	
303	  const type = typeof obj.type === 'string' ? obj.type.toLowerCase() : undefined;
304	  const mode = typeof obj.mode === 'string' ? obj.mode : typeof obj.Mode === 'string' ? obj.Mode : undefined;
305	
306	  let isDir = readEntryFlag(obj, ['isDir', 'is_dir', 'IsDir', 'dir']) ?? false;
307	  if (!isDir && type) isDir = type === 'dir' || type === 'directory';
308	  if (!isDir && mode) isDir = mode.startsWith('d');
309	
310	  let isSymlink = readEntryFlag(obj, ['isSymlink', 'is_symlink', 'symlink']) ?? false;
311	  if (!isSymlink && type) isSymlink = type === 'symlink' || type === 'link';
312	  if (!isSymlink && mode) isSymlink = mode.startsWith('l');
313	
314	  const sizeRaw = obj.size ?? obj.Size;
315	  const size = typeof sizeRaw === 'number' ? sizeRaw : Number(sizeRaw) || 0;
316	
317	  const modTimeRaw = obj.modTime ?? obj.mod_time ?? obj.mtime ?? obj.modified ?? obj.ModTime;
318	  const modTime = typeof modTimeRaw === 'string' ? modTimeRaw : undefined;
319	
320	  return { name, path, isDir, isSymlink, size, mode, modTime };
321	}
