330	  const raw = await apiRequest<{ path?: string; entries?: unknown[]; count?: number }>(
331	    'GET',
332	    `/sprites/${encodeURIComponent(spriteName)}/fs/list?${params.toString()}`
333	  );
334	  const listPath = typeof raw?.path === 'string' && raw.path ? raw.path : path;
335	  const rawEntries = Array.isArray(raw?.entries) ? raw.entries : [];
336	  const entries = rawEntries
337	    .map((entry) => normalizeFileEntry(entry, listPath))
338	    .filter((entry) => entry.name && entry.name !== '.' && entry.name !== '..');
339	  entries.sort((a, b) => {
340	    if (a.isDir !== b.isDir) return a.isDir ? -1 : 1;
341	    return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
342	  });
343	  return { path: listPath, entries, count: entries.length };
344	}
