388	export async function streamService(
389	  spriteName: string,
390	  serviceName: string,
391	  config: ServiceRequest,
392	  onEvent: (event: ServiceLogEvent) => void,
393	  signal?: AbortSignal,
394	  duration: string = '3600s'
395	): Promise<void> {
396	  const token = await getToken();
397	  const url = `${BASE_URL}/sprites/${spriteName}/services/${serviceName}?duration=${duration}`;
398	
399	  const response = await fetch(url, {
400	    method: 'PUT',
401	    headers: {
402	      Authorization: `Bearer ${token}`,
403	      'Content-Type': 'application/json',
404	    },
405	    body: JSON.stringify(config),
406	    signal,
407	  });
408	
409	  if (response.status === 401) throw new AppError('unauthorized', 'Unauthorized');
410	  if (response.status === 404) throw new AppError('notFound', 'Not found');
411	  if (!response.ok) {
412	    throw new AppError('serverError', `Service error ${response.status}`, response.status);
413	  }
414	
415	  const reader = response.body?.getReader();
416	  const decoder = new TextDecoder();
417	  let buffer = '';
418	  const consumeChunk = (chunk: string) => {
419	    buffer += chunk;
420	    const lines = buffer.split('\n');
421	    buffer = lines.pop() ?? '';
422	
423	    for (const line of lines) {
424	      const event = parseServiceEventLine(line);
425	      if (event) onEvent(event);
426	    }
427	  };
428	
429	  if (reader) {
430	    while (true) {
431	      const { done, value } = await reader.read();
432	      if (done) break;
433	      consumeChunk(decoder.decode(value, { stream: true }));
434	    }
435	  } else {
436	    // Some RN runtimes don't expose a streaming reader; fall back to full text parse.
437	    const text = await response.text();
438	    if (text) consumeChunk(text.endsWith('\n') ? text : `${text}\n`);
439	  }
440	
441	  // Process remaining buffer
442	  if (buffer.trim()) {
443	    const event = parseServiceEventLine(buffer);
444	    if (event) onEvent(event);
445	  }
446	}
