505	export interface ExecStdinWriter {
506	  write: (text: string) => void;
507	  writeBytes: (bytes: Uint8Array) => void;
508	}
509	
510	export interface StreamExecOptions {
511	  attachSessionId?: string;
512	  path?: string;
513	  maxRunAfterDisconnect?: string;
514	  tty?: boolean;
515	  stdin?: boolean;
516	  onStdinReady?: (writer: ExecStdinWriter) => void;
517	  onSessionId?: (sessionId: string) => void;
518	  onDisconnectBeforeExit?: () => void;
519	}
520	
521	function createAbortError(): Error {
522	  const error = new Error('Aborted');
523	  error.name = 'AbortError';
524	  return error;
525	}
526	
527	function makeExecWsUrl(
528	  spriteName: string,
529	  command: string[],
530	  token: string,
531	  options: StreamExecOptions
532	): string {
533	  if (options.attachSessionId) {
534	    const params = new URLSearchParams();
535	    if (Platform.OS === 'web') params.set('token', token);
536	    const query = params.toString();
537	    return `${WS_BASE_URL}/sprites/${encodeURIComponent(spriteName)}/exec/${encodeURIComponent(options.attachSessionId)}${query ? `?${query}` : ''}`;
538	  }
539	
540	  const params = new URLSearchParams();
541	  for (const part of command) params.append('cmd', part);
542	  params.set('path', options.path ?? command[0] ?? 'bash');
543	  params.set('tty', options.tty ? 'true' : 'false');
544	  params.set('stdin', options.stdin ? 'true' : 'false');
545	  params.set('max_run_after_disconnect', options.maxRunAfterDisconnect ?? '0s');
546	  if (Platform.OS === 'web') params.set('token', token);
547	
548	  return `${WS_BASE_URL}/sprites/${encodeURIComponent(spriteName)}/exec?${params.toString()}`;
549	}
550	
551	async function messageDataToBytes(data: unknown): Promise<Uint8Array | undefined> {
552	  if (data instanceof ArrayBuffer) return new Uint8Array(data);
553	  if (ArrayBuffer.isView(data)) {
554	    return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
555	  }
556	  if (typeof Blob !== 'undefined' && data instanceof Blob) {
557	    return new Uint8Array(await data.arrayBuffer());
558	  }
559	  return undefined;
560	}
561	
562	async function messageDataToText(data: unknown): Promise<string> {
563	  if (typeof data === 'string') return data;
564	  const bytes = await messageDataToBytes(data);
565	  if (bytes) return new TextDecoder().decode(bytes);
566	  return String(data ?? '');
567	}
568	
569	function extractExecSessionId(payload: unknown): string | undefined {
570	  if (!payload || typeof payload !== 'object') return undefined;
571	  const obj = payload as Record<string, unknown>;
572	  const direct = obj.session_id ?? obj.sessionId;
573	  if (typeof direct === 'string') return direct;
574	  if (typeof direct === 'number') return String(direct);
575	  return undefined;
576	}
577	
578	function parseExecExitCode(bytes: Uint8Array): number {
579	  if (bytes.length === 0) return 0;
580	  if (bytes.length === 1) return bytes[0];
581	
582	  const text = new TextDecoder().decode(bytes).trim();
583	  const parsed = Number(text);
584	  return Number.isFinite(parsed) ? parsed : bytes[0];
585	}
586	
587	function stringLooksLikeBinaryFrame(text: string): boolean {
588	  if (!text) return false;
589	  const streamId = text.charCodeAt(0);
590	  return streamId >= 0 && streamId <= 4;
591	}
592	
593	function stringToBytes(text: string): Uint8Array {
594	  return Uint8Array.from(Array.from(text, (ch) => ch.charCodeAt(0) & 0xff));
595	}
596	
597	function textToUtf8Bytes(text: string): Uint8Array {
598	  if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(text);
599	
600	  const encoded = unescape(encodeURIComponent(text));
601	  return Uint8Array.from(Array.from(encoded, (ch) => ch.charCodeAt(0) & 0xff));
602	}
603	
604	function makeExecStdinFrame(payload: Uint8Array): ArrayBuffer {
605	  const frame = new Uint8Array(payload.length + 1);
606	  frame[0] = 0;
607	  frame.set(payload, 1);
608	  return frame.buffer;
609	}
