611	/**
612	 * Stream a one-shot command through the Exec API.
613	 *
614	 * Chat turns must not use the Services API: services are persistent supervised
615	 * processes and may be restarted by the sprite service manager, replaying the
616	 * same prompt into `claude --resume`. Exec sessions do not auto-restart, and
617	 * `max_run_after_disconnect` explicitly controls disconnect behavior.
618	 */
619	export async function streamExec(
620	  spriteName: string,
621	  command: string[],
622	  onEvent: (event: ServiceLogEvent) => void,
623	  signal?: AbortSignal,
624	  options: StreamExecOptions = {}
625	): Promise<void> {
626	  const token = await getToken();
627	  const url = makeExecWsUrl(spriteName, command, token, options);
628	  const stdoutDecoder = new TextDecoder();
629	  const stderrDecoder = new TextDecoder();
630	
631	  return new Promise((resolve, reject) => {
632	    if (signal?.aborted) {
633	      reject(createAbortError());
634	      return;
635	    }
636	
637	    let socket: WebSocket | null = null;
638	    let settled = false;
639	    let sawExit = false;
640	
641	    const cleanup = () => {
642	      signal?.removeEventListener('abort', handleAbort);
643	      if (socket) {
644	        socket.onopen = null;
645	        socket.onmessage = null;
646	        socket.onerror = null;
647	        socket.onclose = null;
648	      }
649	    };
650	
651	    const settle = (err?: Error) => {
652	      if (settled) return;
653	      settled = true;
654	      cleanup();
655	      if (err) {
656	        reject(err);
657	      } else {
658	        onEvent({ type: 'complete' });
659	        resolve();
660	      }
661	    };
662	
663	    const closeSocket = () => {
664	      if (!socket) return;
665	      if (socket.readyState === WebSocket.CLOSED || socket.readyState === WebSocket.CLOSING) return;
666	      socket.close();
667	    };
668	
669	    const writeStdinBytes = (bytes: Uint8Array) => {
670	      if (!socket || socket.readyState !== WebSocket.OPEN) {
671	        throw new AppError('networkError', 'Exec WebSocket is not open');
672	      }
673	      socket.send(makeExecStdinFrame(bytes));
674	    };
675	
676	    const stdinWriter: ExecStdinWriter = {
677	      write: (text: string) => writeStdinBytes(textToUtf8Bytes(text)),
678	      writeBytes: writeStdinBytes,
679	    };
680	
681	    function handleAbort() {
682	      closeSocket();
683	      settle(createAbortError());
684	    }
685	
686	    const handleJsonMessage = (payload: unknown): boolean => {
687	      if (!payload || typeof payload !== 'object') return false;
688	      const obj = payload as Record<string, unknown>;
689	      const sessionId = extractExecSessionId(obj);
690	      if (sessionId) options.onSessionId?.(sessionId);
691	
692	      if (obj.type === 'session_info') {
693	        onEvent({ type: 'started' });
694	        return true;
695	      }
696	
697	      if (obj.type === 'exit') {
698	        sawExit = true;
699	        const exitCode =
700	          typeof obj.exit_code === 'number' ? obj.exit_code :
701	          typeof obj.exitCode === 'number' ? obj.exitCode :
702	          0;
703	        onEvent({ type: 'exit', exit_code: exitCode });
704	        closeSocket();
705	        return true;
706	      }
707	
708	      return false;
709	    };
710	
711	    const handleTextMessage = (text: string): boolean => {
712	      try {
713	        return handleJsonMessage(JSON.parse(text));
714	      } catch {
715	        return false;
716	      }
717	    };
718	
719	    const handleBinaryMessage = (bytes: Uint8Array) => {
720	      if (bytes.length === 0) return;
721	      const streamId = bytes[0];
722	      const payload = bytes.slice(1);
723	
724	      if (streamId === 1) {
725	        const data = stdoutDecoder.decode(payload, { stream: true });
726	        if (data) onEvent({ type: 'stdout', data });
727	      } else if (streamId === 2) {
728	        const data = stderrDecoder.decode(payload, { stream: true });
729	        if (data) onEvent({ type: 'stderr', data });
730	      } else if (streamId === 3) {
731	        const stdoutRemainder = stdoutDecoder.decode();
732	        const stderrRemainder = stderrDecoder.decode();
733	        if (stdoutRemainder) onEvent({ type: 'stdout', data: stdoutRemainder });
734	        if (stderrRemainder) onEvent({ type: 'stderr', data: stderrRemainder });
735	        sawExit = true;
736	        onEvent({ type: 'exit', exit_code: parseExecExitCode(payload) });
737	        closeSocket();
738	      }
739	    };
740	
741	    signal?.addEventListener('abort', handleAbort, { once: true });
742	
743	    if (Platform.OS === 'web') {
744	      socket = new WebSocket(url);
745	    } else {
746	      const RNWebSocket = WebSocket as unknown as RNWebSocketCtor;
747	      socket = new RNWebSocket(url, undefined, {
748	        headers: {
749	          Authorization: `Bearer ${token}`,
750	        },
751	      });
752	    }
753	
754	    socket.binaryType = 'arraybuffer';
755	
756	    socket.onopen = () => {
757	      onEvent({ type: 'started' });
758	      try {
759	        options.onStdinReady?.(stdinWriter);
760	      } catch (err) {
761	        settle(err as Error);
762	      }
763	    };
764	
765	    socket.onmessage = async (event) => {
766	      try {
767	        if (typeof event.data === 'string') {
768	          if (stringLooksLikeBinaryFrame(event.data)) {
769	            handleBinaryMessage(stringToBytes(event.data));
770	            return;
771	          }
772	          if (!handleTextMessage(event.data)) {
773	            onEvent({ type: 'stdout', data: event.data });
774	          }
775	          return;
776	        }
777	
778	        const bytes = await messageDataToBytes(event.data);
779	        if (bytes) {
780	          handleBinaryMessage(bytes);
781	          return;
782	        }
783	
784	        const text = await messageDataToText(event.data);
785	        if (!handleTextMessage(text)) {
786	          onEvent({ type: 'stdout', data: text });
787	        }
788	      } catch (err) {
789	        settle(err as Error);
790	      }
791	    };
792	
793	    socket.onerror = () => {
794	      closeSocket();
795	      settle(new AppError('networkError', 'Exec WebSocket error'));
796	    };
797	
798	    socket.onclose = () => {
799	      if (signal?.aborted) {
800	        settle(createAbortError());
801	        return;
802	      }
803	      if (!sawExit) {
804	        if (options.onDisconnectBeforeExit) {
805	          options.onDisconnectBeforeExit();
806	        } else {
807	          onEvent({ type: 'exit', exit_code: 0 });
808	        }
809	      }
810	      settle();
811	    };
812	  });
813	}
