815	/**
816	 * Start a long-running service and let it keep running in the background.
817	 * `streamService` only resolves when the service exits, so this fires it without
818	 * awaiting and resolves `started` once the first lifecycle event arrives (or after
819	 * `settleMs`). Aborting the returned controller stops *streaming logs*; use
820	 * `deleteService` to actually stop the service.
821	 */
822	export function startBackgroundService(
823	  spriteName: string,
824	  serviceName: string,
825	  config: ServiceRequest,
826	  onEvent?: (event: ServiceLogEvent) => void,
827	  settleMs: number = 1500
828	): { controller: AbortController; started: Promise<void> } {
829	  const controller = new AbortController();
830	  const started = new Promise<void>((resolve) => {
831	    let settled = false;
832	    const settle = () => {
833	      if (settled) return;
834	      settled = true;
835	      resolve();
836	    };
837	    const timer = setTimeout(settle, settleMs);
838	    streamService(
839	      spriteName,
840	      serviceName,
841	      config,
842	      (event) => {
843	        onEvent?.(event);
844	        if (event.type === 'started' || event.type === 'stdout' || event.type === 'stderr') {
845	          settle();
846	        }
847	      },
848	      controller.signal
849	    )
850	      .catch((err) => {
851	        if ((err as Error)?.name !== 'AbortError') {
852	          onEvent?.({ type: 'error', data: (err as Error).message });
853	        }
854	      })
855	      .finally(() => {
856	        clearTimeout(timer);
857	        settle();
858	      });
859	  });
860	  return { controller, started };
861	}
