954	/**
955	 * Run a short command on a sprite via the Exec API.
956	 * Creates a temporary exec session and collects stdout.
957	 * Used for simple operations like waking sprites or fetching session info.
958	 */
959	export async function runExec(
960	  spriteName: string,
961	  command: string,
962	  timeout: number = 15
963	): Promise<{ output: string; success: boolean }> {
964	  let output = '';
965	  let exitCode: number | undefined;
966	  const controller = new AbortController();
967	  const timer = setTimeout(() => controller.abort(), timeout * 1000);
968	
969	  try {
970	    await streamExec(
971	      spriteName,
972	      ['bash', '-c', command],
973	      (event) => {
974	        if (event.type === 'stdout' && event.data) {
975	          output += event.data;
976	        } else if (event.type === 'exit') {
977	          exitCode = event.exit_code ?? 0;
978	        }
979	      },
980	      controller.signal,
981	      {
982	        path: '/bin/bash',
983	        maxRunAfterDisconnect: '1s',
984	      }
985	    );
986	  } catch (err: any) {
987	    if (err.name !== 'AbortError') {
988	      exitCode = exitCode ?? 1;
989	    }
990	  } finally {
