973	// Settings Tab — checkpoints, accounts, sprite info, and delete. A lightweight
974	// sub-view switch keeps each nested scroller (CheckpointsList / SpriteAccountsTab)
975	// isolated and leaves room for more settings later.
976	function SettingsTab({
977	  sprite,
978	  isLoading,
979	  spriteName,
980	  workingDirectory,
981	  isActive,
982	  onSpriteUpdated,
983	}: {
984	  sprite: Sprite | null;
985	  isLoading: boolean;
986	  spriteName: string;
987	  workingDirectory: string;
988	  isActive: boolean;
989	  onSpriteUpdated: (sprite: Sprite) => void;
990	}) {
991	  const colors = useTheme();
992	  const [view, setView] = useState<SettingsView>('menu');
993	  const [isDeleting, setIsDeleting] = useState(false);
994	
995	  // Poll sprite status every 5 seconds while the Settings menu is showing.
996	  useEffect(() => {
997	    if (!isActive || view !== 'menu') return;
998	    const interval = setInterval(async () => {
999	      try {
1000	        const s = await api.getSprite(spriteName);
1001	        onSpriteUpdated(s);
1002	      } catch {}
1003	    }, 5000);
1004	    return () => clearInterval(interval);
1005	  }, [isActive, view, spriteName, onSpriteUpdated]);
1006	
1007	  const handleDelete = () => {
1008	    Alert.alert(
1009	      'Delete Sprite',
1010	      `Are you sure you want to delete "${spriteName}"? This action cannot be undone.`,
1011	      [
1012	        { text: 'Cancel', style: 'cancel' },
1013	        {
1014	          text: 'Delete',
1015	          style: 'destructive',
1016	          onPress: async () => {
1017	            setIsDeleting(true);
1018	            try {
1019	              await api.deleteSprite(spriteName);
1020	              router.back();
1021	            } catch (err: any) {
1022	              Alert.alert('Error', err.message ?? 'Failed to delete sprite');
1023	              setIsDeleting(false);
1024	            }
1025	          },
1026	        },
1027	      ]
1028	    );
1029	  };
1030	
1031	  if (view === 'checkpoints') {
1032	    return (
1033	      <SettingsSubView title="Checkpoints" onBack={() => setView('menu')}>
1034	        <CheckpointsList spriteName={spriteName} />
1035	      </SettingsSubView>
1036	    );
1037	  }
1038	
1039	  if (view === 'accounts') {
1040	    return (
1041	      <SettingsSubView title="Accounts" onBack={() => setView('menu')}>
1042	        <SpriteAccountsTab spriteName={spriteName} isActive={isActive} />
1043	      </SettingsSubView>
1044	    );
1045	  }
1046	
1047	  if (isLoading) {
1048	    return (
1049	      <View style={styles.centerView}>
1050	        <ActivityIndicator size="large" color={colors.tint} />
1051	      </View>
1052	    );
1053	  }
1054	
1055	  const infoRows: { label: string; value: string }[] = [];
1056	  if (sprite) {
1057	    infoRows.push(
1058	      { label: 'Name', value: sprite.name },
1059	      { label: 'Status', value: statusDisplayName(sprite.status) },
1060	      { label: 'ID', value: sprite.id }
1061	    );
1062	    if (sprite.url) infoRows.push({ label: 'URL', value: sprite.url });
1063	    if (sprite.created_at) {
1064	      infoRows.push({ label: 'Created', value: new Date(sprite.created_at).toLocaleString() });
1065	    }
1066	    if (sprite.url_settings) infoRows.push({ label: 'Auth', value: sprite.url_settings.auth });
1067	  }
1068	  infoRows.push({ label: 'Work Dir', value: workingDirectory });
1069	
1070	  return (
1071	    <ScrollView style={styles.tabScroll} contentContainerStyle={styles.tabScrollContent}>
1072	      <Text style={[styles.sectionHeader, { color: colors.textSecondary }]}>CONFIGURATION</Text>
1073	      <ConnectRow
1074	        title="Checkpoints"
1075	        subtitle="Create and restore filesystem checkpoints for this sprite."
1076	        onPress={() => setView('checkpoints')}
1077	      />
1078	      <ConnectRow
1079	        title="Accounts"
1080	        subtitle="Connect Claude, Codex, and GitHub accounts for this sprite."
1081	        onPress={() => setView('accounts')}
1082	      />
1083	
1084	      {!sprite ? (
1085	        <Text style={[styles.errorBarText, { color: colors.destructive, marginTop: Spacing.lg }]}>
1086	          Failed to load sprite info
1087	        </Text>
1088	      ) : (
1089	        <>
1090	          <Text style={[styles.sectionHeader, { color: colors.textSecondary }]}>SPRITE INFO</Text>
1091	          {infoRows.map((row) => (
1092	            <View key={row.label} style={[styles.infoRow, { borderBottomColor: colors.border }]}>
1093	              <Text style={[styles.infoLabel, { color: colors.textSecondary }]}>{row.label}</Text>
1094	              <Text
1095	                style={[styles.infoValue, { color: colors.text }]}
1096	                numberOfLines={1}
1097	                selectable
1098	              >
1099	                {row.value}
1100	              </Text>
1101	            </View>
1102	          ))}
1103	        </>
1104	      )}
1105	
1106	      <View style={styles.deleteButtonContainer}>
1107	        <Pressable
1108	          style={[styles.deleteButton, { borderColor: colors.destructive }]}
1109	          onPress={handleDelete}
1110	          disabled={isDeleting}
1111	        >
1112	          {isDeleting ? (
1113	            <ActivityIndicator size="small" color={colors.destructive} />
1114	          ) : (
1115	            <Text style={[styles.deleteButtonText, { color: colors.destructive }]}>
1116	              Delete Sprite
1117	            </Text>
1118	          )}
1119	        </Pressable>
1120	      </View>
1121	    </ScrollView>
1122	  );
1123	}
