1	import { ChatContent, ChatMessage, ToolResultCard, ToolUseCard, makeId } from '@/models/chat';
2	import { JSONValue } from '@/models/claude-events';
3	import { runExec } from './api';
4	
5	/**
6	 * Reads Claude Code's own on-disk session transcripts from a sprite — the same
7	 * data `claude --resume` shows. Claude stores one JSONL file per session under
8	 * `~/.claude/projects/<encoded-cwd>/<session-id>.jsonl`, where each line is an
9	 * event ({type:"user"|"assistant"|"system"|"result", message, cwd, timestamp}).
10	 *
11	 * Because these live on disk (not in the phone), they survive the process
12	 * exiting, the app being closed, or even a fresh install — letting the app
13	 * mirror the desktop "console + claude --resume" / "sessions list" experience.
14	 */
15	
16	export interface ClaudeSessionSummary {
17	  /** Session UUID — the value you pass to `claude --resume <id>`. */
18	  id: string;
19	  /** Working directory the session ran in (resume must use the same cwd). */
