1	import { useCallback, useRef, useState } from 'react';
2	import {
3	  AgentProvider,
4	  ChatContent,
5	  ChatMessage,
6	  ChatStatus,
7	  ToolResultCard,
8	  ToolUseCard,
9	  TurnOutcome,
10	  isCodexProvider,
11	  makeId,
12	  providerDisplayName,
13	} from '@/models/chat';
14	import {
15	  ClaudeAssistantEvent,
16	  ClaudeResultEvent,
17	  ClaudeStreamEvent,
18	  ClaudeSystemEvent,
19	  ClaudeToolResultEvent,
20	} from '@/models/claude-events';
21	import { CodexStreamEvent } from '@/models/codex-events';
22	import { ServiceLogEvent } from '@/models/service';
23	import { ClaudeStreamParser, stripLogTimestamps } from '@/services/claude-stream';
24	import { CodexStreamParser } from '@/services/codex-stream';
25	import { streamCodexAppServerTurn } from '@/services/codex-app-server';
26	import { readClaudeSessionMessages } from '@/services/claude-sessions';
27	import { readCodexSessionMessages } from '@/services/codex-sessions';
28	import * as api from '@/services/api';
29	import { ensureProvisionedOnce } from '@/services/provision';
30	import { ActiveChatRun, chatRepository } from '@/services/chat-repository';
31	import { getSetting } from '@/services/storage';
32	import {
33	  buildFallbackPrompt,
34	  buildProcessGroupKillCommand,
35	  buildTurnNotifySuffix,
36	  classifyCodexAuthIssue,
37	  codexEventDebugLabel,
38	  compactDebugChunk,
39	  conversationSignature,
40	  countUserMessages,
41	  elapsedSince,
42	  isHeartbeatStderr,
43	  mergeTranscript,
44	  nextAssistantAfterUser,
45	  safeTaskName,
46	  shellQuote,
47	  withSpriteTaskHeartbeat,
48	} from '@/services/chat-helpers';
49	
50	const CODEX_DEFAULT_MODEL_LABEL = 'Codex default';
51	const CHAT_MAX_RUN_AFTER_DISCONNECT = '8h';
52	
53	interface SessionIds {
54	  claudeSessionId?: string;
55	  codexSessionId?: string;
56	}
57	
58	/** A send that failed before anything launched on the sprite — safe to retry. */
59	interface FailedSend {
60	  prompt: string;
61	  userMessageId: string;
62	  assistantMessageId: string;
63	}
64	
65	/** A message written while a turn was in flight, waiting to be sent. */
66	export interface QueuedPrompt {
67	  id: string;
68	  text: string;
69	}
70	
71	interface UseChatOptions {
72	  spriteName: string;
73	  chatId: string;
74	  workingDirectory: string;
75	  provider: AgentProvider;
76	  initialClaudeSessionId?: string;
77	  initialCodexSessionId?: string;
78	  initialActiveRun?: ActiveChatRun;
79	  onSessionIdsChange?: (sessionIds: SessionIds) => void;
80	  onActiveRunChange?: (activeRun: ActiveChatRun | undefined) => void;
81	  onCodexAuthIssue?: (message: string) => void;
82	}
83	
84	function debugChat(...args: unknown[]) {
85	  if (!__DEV__) return;
86	  // eslint-disable-next-line no-console
87	  console.log('[chat-debug]', ...args);
88	}
89	
90	type ChatTurnTiming = {
91	  startedAt?: number;
92	  firstStdoutAt?: number;
93	  firstStderrAt?: number;
94	  firstParsedAt?: number;
95	  firstAssistantAt?: number;
96	};
97	
98	export function useChat(options: UseChatOptions) {
99	  const { spriteName, chatId, workingDirectory, provider } = options;
100	
101	  const [messages, setMessages] = useState<ChatMessage[]>([]);
102	  const [status, setStatus] = useState<ChatStatus>('idle');
103	  const [modelName, setModelName] = useState<string | undefined>();
104	  const [errorMessage, setErrorMessage] = useState<string | undefined>();
105	  const [inputText, setInputText] = useState('');
106	  const [codexAuthIssue, setCodexAuthIssue] = useState<string | undefined>();
107	  const [failedSend, setFailedSendState] = useState<FailedSend | undefined>();
108	  // In-memory only, per chat: queued messages don't survive app restarts.
109	  const [queuedPrompts, setQueuedPromptsState] = useState<QueuedPrompt[]>([]);
110	
111	  const claudeSessionIdRef = useRef<string | undefined>(options.initialClaudeSessionId);
112	  const codexSessionIdRef = useRef<string | undefined>(options.initialCodexSessionId);
113	  const activeRunRef = useRef<ActiveChatRun | undefined>(options.initialActiveRun);
114	  const execSessionIdRef = useRef<string | undefined>(undefined);
115	  const abortRef = useRef<AbortController | null>(null);
116	  const claudeParserRef = useRef(new ClaudeStreamParser());
117	  const codexParserRef = useRef(new CodexStreamParser());
118	  const loadRequestRef = useRef(0);
119	  const loadedChatIdRef = useRef<string | undefined>(undefined);
120	  const messagesRef = useRef<ChatMessage[]>([]);
121	  const activeUserMessageIdRef = useRef<string | undefined>(undefined);
122	  const activeAssistantMessageIdRef = useRef<string | undefined>(undefined);
123	  const toolUseIndexRef = useRef<Map<string, { messageIndex: number; toolName: string }>>(new Map());
124	  const processedUUIDsRef = useRef<Set<string>>(new Set());
125	  const statusRef = useRef<ChatStatus>('idle');
126	  const assistantTextSeenRef = useRef(false);
127	  const serviceEventsSeenRef = useRef(0);
128	  const codexStderrRef = useRef('');
129	  const codexSawAssistantRef = useRef(false);
130	  const agentTurnCompleteRef = useRef(false);
131	  const turnTimingRef = useRef<ChatTurnTiming>({});
132	  const detachingControllersRef = useRef<Set<AbortController>>(new Set());
133	  const processServiceEventRef = useRef<(event: ServiceLogEvent) => void>(() => {});
134	  const reconnectTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
135	  const reconnectAttemptRef = useRef(0);
136	  const attachToRunRef = useRef<(run: ActiveChatRun, loadRequest: number) => void>(() => {});
137	  const failedSendRef = useRef<FailedSend | undefined>(undefined);
138	  const queuedPromptsRef = useRef<QueuedPrompt[]>([]);
139	  const sendMessageRef = useRef<(text?: string) => Promise<void>>(async () => {});
140	
141	  const setFailedSend = useCallback((value: FailedSend | undefined) => {
142	    failedSendRef.current = value;
143	    setFailedSendState(value);
144	  }, []);
145	
146	  const setQueuedPrompts = useCallback((value: QueuedPrompt[]) => {
147	    queuedPromptsRef.current = value;
148	    setQueuedPromptsState(value);
149	  }, []);
150	
151	  /** Fire the next queued message once the chat is fully idle again. */
152	  const maybeSendNextQueued = useCallback(() => {
153	    if (queuedPromptsRef.current.length === 0) return;
154	    if (statusRef.current !== 'idle' || activeRunRef.current) return;
155	    const [next, ...rest] = queuedPromptsRef.current;
156	    setQueuedPrompts(rest);
157	    // Defer one tick so the finished turn's state fully settles first.
158	    setTimeout(() => {
159	      sendMessageRef.current(next.text);
160	    }, 0);
161	  }, [setQueuedPrompts]);
162	
163	  const setStatusTracked = useCallback((s: ChatStatus) => {
164	    statusRef.current = s;
165	    setStatus(s);
166	  }, []);
167	
168	  const emitSessionIds = useCallback(() => {
169	    options.onSessionIdsChange?.({
170	      claudeSessionId: claudeSessionIdRef.current,
171	      codexSessionId: codexSessionIdRef.current,
172	    });
173	  }, [options.onSessionIdsChange]);
174	
175	  const setActiveRun = useCallback(
176	    (activeRun: ActiveChatRun | undefined) => {
177	      activeRunRef.current = activeRun;
178	      options.onActiveRunChange?.(activeRun);
179	    },
180	    [options.onActiveRunChange]
181	  );
182	
183	  const setClaudeSessionId = useCallback(
184	    (sessionId: string | undefined) => {
185	      if (claudeSessionIdRef.current === sessionId) return;
186	      claudeSessionIdRef.current = sessionId;
187	      emitSessionIds();
188	    },
189	    [emitSessionIds]
190	  );
191	
192	  const setCodexSessionId = useCallback(
193	    (sessionId: string | undefined) => {
194	      if (codexSessionIdRef.current === sessionId) return;
195	      codexSessionIdRef.current = sessionId;
196	      emitSessionIds();
197	    },
198	    [emitSessionIds]
199	  );
200	
201	  const isStreaming =
202	    status === 'streaming' ||
203	    status === 'connecting' ||
204	    status === 'reconnecting' ||
205	    activeRunRef.current !== undefined;
206	
207	  const updateMessages = useCallback((updater: (prev: ChatMessage[]) => ChatMessage[]) => {
208	    setMessages((prev) => {
209	      const next = updater(prev);
210	      messagesRef.current = next;
211	      return next;
212	    });
213	  }, []);
214	
215	  const persistMessages = useCallback(
216	    async (msgs?: ChatMessage[]) => {
217	      await chatRepository.setMessages(chatId, msgs ?? messagesRef.current);
218	    },
219	    [chatId]
220	  );
221	
222	  const syncClaudeTranscript = useCallback(
223	    async (
224	      loadRequest: number,
225	      resumeId: string | undefined,
226	      opts?: { allowReconnecting?: boolean }
227	    ) => {
228	      if (provider !== 'claude' || !resumeId) return;
229	
230	      try {
231	        const transcript = await readClaudeSessionMessages(spriteName, resumeId);
232	        if (loadRequest !== loadRequestRef.current) return;
233	        const statusOk =
234	          statusRef.current === 'idle' ||
235	          (opts?.allowReconnecting === true && statusRef.current === 'reconnecting');
236	        if (!statusOk) return;
237	        if (transcript.length === 0) return;
238	        const local = messagesRef.current;
239	        const transcriptTurns = countUserMessages(transcript);
240	        const localTurns = countUserMessages(local);
241	        // The app may already have persisted the user's in-flight turn before
242	        // it was closed. In that case the turn counts are equal, but the
243	        // transcript can now contain the completed assistant response.
244	        if (local.length !== 0 && transcriptTurns < localTurns) return;
245	        const merged = mergeTranscript(local, transcript);
246	        if (conversationSignature(merged) === conversationSignature(local)) return;
247	        messagesRef.current = merged;
248	        setMessages(merged);
249	        await chatRepository.setMessages(chatId, merged);
250	      } catch {
251	        // Offline / no transcript yet — keep the local copy.
252	      }
253	    },
254	    [chatId, provider, spriteName]
255	  );
256	
257	  // Codex counterpart of syncClaudeTranscript: pull the on-disk rollout for a
258	  // resumed Codex thread so turns that finished while the app was away (or ran
259	  // from a terminal) are recovered — the same history `codex exec resume` sees.
260	  const syncCodexTranscript = useCallback(
261	    async (
262	      loadRequest: number,
263	      resumeId: string | undefined,
264	      opts?: { allowReconnecting?: boolean }
265	    ) => {
266	      if (!isCodexProvider(provider) || !resumeId) return;
267	
268	      try {
269	        const transcript = await readCodexSessionMessages(spriteName, resumeId);
270	        if (loadRequest !== loadRequestRef.current) return;
271	        const statusOk =
272	          statusRef.current === 'idle' ||
273	          (opts?.allowReconnecting === true && statusRef.current === 'reconnecting');
274	        if (!statusOk) return;
275	        if (transcript.length === 0) return;
276	        const local = messagesRef.current;
277	        const transcriptTurns = countUserMessages(transcript);
278	        const localTurns = countUserMessages(local);
279	        if (local.length !== 0 && transcriptTurns < localTurns) return;
280	        const merged = mergeTranscript(local, transcript);
281	        if (conversationSignature(merged) === conversationSignature(local)) return;
282	        messagesRef.current = merged;
283	        setMessages(merged);
284	        await chatRepository.setMessages(chatId, merged);
285	      } catch {
286	        // Offline / no rollout yet — keep the local copy.
287	      }
288	    },
289	    [chatId, provider, spriteName]
290	  );
291	
292	  const clearReconnectTimer = useCallback(() => {
293	    if (reconnectTimerRef.current) {
294	      clearTimeout(reconnectTimerRef.current);
295	      reconnectTimerRef.current = null;
296	    }
297	  }, []);
298	
299	  /** Clear all active-turn state and pull the final on-disk transcript. */
300	  const finishActiveRun = useCallback(
301	    async (
302	      activeRun: ActiveChatRun,
303	      loadRequest: number,
304	      setIdle: boolean,
305	      opts?: { autoSendQueued?: boolean }
306	    ) => {
307	      execSessionIdRef.current = undefined;
308	      activeUserMessageIdRef.current = undefined;
309	      activeAssistantMessageIdRef.current = undefined;
310	      assistantTextSeenRef.current = false;
311	      if (activeRunRef.current?.execSessionId === activeRun.execSessionId) {
312	        setActiveRun(undefined);
313	      }
314	      if (setIdle) setStatusTracked('idle');
315	      await syncClaudeTranscript(loadRequest, claudeSessionIdRef.current);
316	      await syncCodexTranscript(loadRequest, codexSessionIdRef.current);
317	      await persistMessages();
318	      if (opts?.autoSendQueued) maybeSendNextQueued();
319	    },
320	    [maybeSendNextQueued, persistMessages, setActiveRun, setStatusTracked, syncClaudeTranscript, syncCodexTranscript]
321	  );
322	
323	  /**
324	   * Keep trying to get back to a still-running turn. Each tick first probes
325	   * the exec-session list over HTTP: API unreachable → back off and try again
326	   * (the network is down); session gone → the run finished while we were away,
327	   * finalize from the on-disk transcript; session alive → reattach the socket.
328	   */
329	  const scheduleReconnect = useCallback(
330	    (activeRun: ActiveChatRun, loadRequest: number) => {
331	      clearReconnectTimer();
332	      const attempt = reconnectAttemptRef.current + 1;
333	      reconnectAttemptRef.current = attempt;
334	      const delayMs = Math.min(30_000, 1000 * 2 ** Math.min(attempt - 1, 5));
335	      debugChat('reconnect scheduled', provider, `attempt=${attempt}`, `delayMs=${delayMs}`);
336	      setStatusTracked('reconnecting');
337	      reconnectTimerRef.current = setTimeout(async () => {
338	        reconnectTimerRef.current = null;
339	        if (loadRequest !== loadRequestRef.current) return;
340	        if (activeRunRef.current?.execSessionId !== activeRun.execSessionId) return;
341	
342	        let sessions: api.ExecSession[];
343	        try {
344	          sessions = await api.listExecSessionsStrict(spriteName);
345	        } catch (err: any) {
346	          if (err?.code === 'notFound' || err?.code === 'unauthorized' || err?.code === 'noToken') {
347	            // The sprite (or our access to it) is gone — stop retrying.
348	            setErrorMessage(err?.message ?? 'Sprite unreachable');
349	            await finishActiveRun(activeRun, loadRequest, true);
350	            return;
351	          }
352	          scheduleReconnect(activeRun, loadRequest);
353	          return;
354	        }
355	        if (loadRequest !== loadRequestRef.current) return;
356	        if (activeRunRef.current?.execSessionId !== activeRun.execSessionId) return;
357	
358	        if (!sessions.some((s) => s.id === activeRun.execSessionId)) {
359	          debugChat('reconnect: run finished while away', provider, activeRun.execSessionId);
360	          await finishActiveRun(activeRun, loadRequest, true, { autoSendQueued: true });
361	          return;
362	        }
363	        attachToRunRef.current(activeRun, loadRequest);
364	      }, delayMs);
365	    },
366	    [clearReconnectTimer, finishActiveRun, provider, setStatusTracked, spriteName]
367	  );
368	
369	  /**
370	   * (Re)attach to a running turn's exec session. Pulls the on-disk transcript
371	   * first so output that streamed while we were disconnected renders
372	   * immediately — the attach socket only carries output from now on.
373	   */
374	  const attachToRun = useCallback(
375	    async (activeRun: ActiveChatRun, loadRequest: number) => {
376	      if (abortRef.current) {
377	        debugChat('attach skipped: a stream is already active', provider);
378	        return;
379	      }
380	      activeUserMessageIdRef.current = activeRun.userMessageId;
381	      activeAssistantMessageIdRef.current = activeRun.assistantMessageId;
382	      execSessionIdRef.current = activeRun.execSessionId;
383	      processedUUIDsRef.current = new Set();
384	      claudeParserRef.current.reset();
385	      codexParserRef.current.reset();
386	      codexStderrRef.current = '';
387	      codexSawAssistantRef.current = false;
388	      agentTurnCompleteRef.current = false;
389	      serviceEventsSeenRef.current = 0;
390	      turnTimingRef.current = { startedAt: Date.now() };
391	      setStatusTracked('reconnecting');
392	
393	      await syncClaudeTranscript(loadRequest, claudeSessionIdRef.current, {
394	        allowReconnecting: true,
395	      });
396	      await syncCodexTranscript(loadRequest, codexSessionIdRef.current, {
397	        allowReconnecting: true,
398	      });
399	      if (activeRunRef.current?.execSessionId !== activeRun.execSessionId) return;
400	      if (abortRef.current) return;
401	
402	      const controller = new AbortController();
403	      let disconnectedBeforeExit = false;
404	      abortRef.current = controller;
405	      try {
406	        await api.streamExec(
407	          spriteName,
408	          [],
409	          (event) => {
410	            if (abortRef.current !== controller) return;
411	            if (reconnectAttemptRef.current !== 0) reconnectAttemptRef.current = 0;
412	            processServiceEventRef.current(event);
413	          },
414	          controller.signal,
415	          {
416	            attachSessionId: activeRun.execSessionId,
417	            onDisconnectBeforeExit: () => {
418	              disconnectedBeforeExit = true;
419	            },
420	          }
421	        );
